package com.campus.personnel.infrastructure.persistence.entity;
import java.time.Instant; import java.util.UUID; import com.campus.personnel.domain.*; import jakarta.persistence.*; import org.springframework.data.annotation.CreatedDate; import org.springframework.data.annotation.LastModifiedDate; import org.springframework.data.jpa.domain.support.AuditingEntityListener;
@Entity @Table(name="faculty_staff") @EntityListeners(AuditingEntityListener.class) public class FacultyStaffEntity { @Id private UUID id; @Column(name="personnel_number",nullable=false,length=32) private String personnelNumber; @Column(name="full_name",nullable=false,length=160) private String fullName; @Column(length=320) private String email; @Enumerated(EnumType.STRING) @Column(name="personnel_type",nullable=false,length=20) private PersonnelType personnelType; @Column(name="organization_unit_id",nullable=false) private UUID organizationUnitId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PersonnelStatus status; @Version @Column(name="row_version",nullable=false) private long rowVersion; @CreatedDate @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @LastModifiedDate @Column(name="updated_at",nullable=false) private Instant updatedAt; protected FacultyStaffEntity(){} public FacultyStaffEntity(UUID id){this.id=id;} public UUID getId(){return id;} public String getPersonnelNumber(){return personnelNumber;} public String getFullName(){return fullName;} public String getEmail(){return email;} public PersonnelType getPersonnelType(){return personnelType;} public UUID getOrganizationUnitId(){return organizationUnitId;} public PersonnelStatus getStatus(){return status;} public long getRowVersion(){return rowVersion;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void update(String n,String name,String e,PersonnelType t,UUID u,PersonnelStatus s){personnelNumber=n;fullName=name;email=e;personnelType=t;organizationUnitId=u;status=s;} }
